```javascript
export default {
  async fetch(request) {
    const url = new URL(request.url);
    const imagePath = url.pathname;

    // Kiểm tra xem request có phải là hình ảnh hay không
    if (imagePath.match(/\.(jpg|jpeg|png|webp)$/i)) {
      // Lấy hình ảnh gốc từ origin server
      const response = await fetch(`https://origin.example.com${imagePath}`);
      const imageBuffer = await response.arrayBuffer();

      // Tối ưu hóa hình ảnh bằng Cloudflare Images
      const optimizedImage = await optimizeImage(imageBuffer, {
        format: 'webp',
        quality: 80,
        width: 1200
      });

      // Trả về hình ảnh đã được tối ưu hóa
      return new Response(optimizedImage, {
        headers: {
          'Content-Type': 'image/webp'
        }
      });
    }

    // Đối với các request không phải hình ảnh, lấy dữ liệu từ origin server
    return fetch(request);
  }
};

// Hàm helper để tối ưu hóa hình ảnh bằng Cloudflare Images
async function optimizeImage(buffer, options) {
  // Phần triển khai thực tế sẽ sử dụng Cloudflare Images API
  // Đây là phần giữ chỗ (placeholder) cho triển khai thực tế
  return buffer;
}
```

Script này sẽ chặn các request hình ảnh, tối ưu hóa chúng bằng Cloudflare Images và trả về phiên bản đã được tối ưu cho người dùng. Các hình ảnh gốc sẽ được lấy từ origin server (trong trường hợp này là example.com), sau đó được xử lý trước khi phân phối tới client.
